            !IsComputed ? "uncomputed" : $"L={length:F2} [" + string.Join(", ", spans) + "]";

        // ── v1/v2 → v3 ──

        /// <summary>
        /// Converts one v1/v2 edge (kind, mountable wallSpans, openings = walkable stretches,
        /// everything else blocked) to v3 spans, painted the same way a bake paints
        /// (<see cref="RectSpanPainter"/>): blocked stretches are wall when the old edge had a
        /// matched wall (kind wall/window/door/opening) and the plain-wall stretches
        /// (`wallSpans`) are wall on any edge; windows = blocked minus plain wall; door /
        /// opening stretches paint opening (`to` → touches); "rect" stretches become adjacent
        /// openings (`touches`); "open" stretches stay unknown. An edge baked before openings existed:
        /// wall/window = all wall; door/opening = wallSpans wall, the rest opening.
        /// `length` ≤ 0 = the farthest stretch named.
        /// </summary>
        public static RectEdgeBorder FromLegacy(string kind, float[] wallSpans, float wallHeightM, float planeOffsetM,
            RectOpening[] openings, bool openingsBaked, float length)
        {
            if (string.IsNullOrEmpty(kind)) return Unclassified;
            wallSpans = wallSpans ?? Array.Empty<float>();
            openings = openings ?? Array.Empty<RectOpening>();
            if (!(length > 0f))
            {
                float far = 0f;
                for (int i = 0; i < wallSpans.Length; i++) far = Math.Max(far, wallSpans[i]);
                for (int i = 0; i < openings.Length; i++) far = Math.Max(far, openings[i].b);
                if (!(far > 0f)) return new RectEdgeBorder(kind, 0f, null, null);
                length = far;
            }
            bool matched = kind == "wall" || kind == "window" || kind == "door" || kind == "opening";
            var p = new RectSpanPainter(length);
            if (!openingsBaked)
            {
                if (kind == "wall" || kind == "window")
                    p.Paint(0f, length, new RectSpan(0f, 0f, RectSpanKind.Wall, height: wallHeightM, offset: planeOffsetM, window: kind == "window"));
                else if (kind == "door" || kind == "opening")
                {
                    float u = 0f;
                    for (int i = 0; i + 1 < wallSpans.Length; i += 2)
                    {
                        p.Paint(wallSpans[i], wallSpans[i + 1], new RectSpan(0f, 0f, RectSpanKind.Wall, height: wallHeightM, offset: planeOffsetM));
                        if (wallSpans[i] > u) p.Paint(u, wallSpans[i], new RectSpan(0f, 0f, RectSpanKind.Opening, kind));
                        u = Math.Max(u, wallSpans[i + 1]);
                    }
                    if (length > u) p.Paint(u, length, new RectSpan(0f, 0f, RectSpanKind.Opening, kind));
                }
                return p.Build(null, RectSpanPainter.DefaultSnapM);
            }
            if (matched)
            {
                // Blocked = the edge minus its walkable list → wall; plain wall over it below.
                float u = 0f;
                var sorted = new List<RectOpening>(openings);
                sorted.Sort((x, y) => x.a.CompareTo(y.a));
                foreach (var o in sorted)
                {
                    if (o.a > u + 1e-3f) p.Paint(u, o.a, new RectSpan(0f, 0f, RectSpanKind.Wall, height: wallHeightM, offset: planeOffsetM, window: true));
                    u = Math.Max(u, o.b);
                }
                if (length > u + 1e-3f) p.Paint(u, length, new RectSpan(0f, 0f, RectSpanKind.Wall, height: wallHeightM, offset: planeOffsetM, window: true));
            }
            for (int i = 0; i + 1 < wallSpans.Length; i += 2)
                p.Paint(wallSpans[i], wallSpans[i + 1], new RectSpan(0f, 0f, RectSpanKind.Wall, height: wallHeightM, offset: planeOffsetM), force: true);
            foreach (var o in openings)
            {
                if (o.type == RectOpening.Door || o.type == RectOpening.Opening)
                    p.Paint(o.a, o.b, new RectSpan(0f, 0f, RectSpanKind.Opening, o.type));
                if (o.type == RectOpening.Rect && o.to != null) p.Adjoin(o.a, o.b, o.to);
                else if (o.to != null) p.Touch(o.a, o.b, o.to);
            }
            return p.Build(null, RectSpanPainter.DefaultSnapM);
        }
    }

    /// <summary>
    /// SPAN PAINTING — the v3 bake, step for step (RECT_EDGES_SPEC.md §1):
    ///   1. init: [0, length] unknown;
    ///   2. Paint(wall …) — a wall never covers an opening; windows paint as
    ///      wall with `window` (over plain wall they only set the flag);
    ///   3. Paint(opening …) on top — an opening overrides a wall;
    ///   4. Touch(a, b, rectId) — an attribute, never a kind change;
    ///   5. Build: merge equal neighbours, absorb slivers, snap boundaries to
    ///      the previous bake's within a few cm (no flicker while scanning).
    /// Precedence: opening &gt; wall &gt; unknown. Pure, Unity-free.
    /// </summary>
    public sealed class RectSpanPainter
    {
        /// Narrowest opening kept (a person does not fit through less).
        public const float MinOpeningM = 0.3f;
        /// Narrowest wall / unknown span kept.
        public const float MinSpanM = 0.15f;
        /// Boundaries within this of a boundary of the previous bake snap to it.
        public const float DefaultSnapM = 0.03f;

        public readonly float length;
        private readonly List<RectSpan> _spans = new List<RectSpan>();

        public RectSpanPainter(float length)
        {
            this.length = Math.Max(0f, length);
            _spans.Add(new RectSpan(0f, this.length, RectSpanKind.Unknown));
        }

        /// Continue painting an existing side (its spans must tile [0, length]).
        public RectSpanPainter(RectEdgeBorder side)
        {
            length = side.length;
            if (side.IsComputed && side.length > 0f) _spans.AddRange(side.spans);
            else _spans.Add(new RectSpan(0f, length, RectSpanKind.Unknown));
        }

        /// Paints [a, b] with `span`'s attributes where it ranks at least the existing
        /// span (unknown &lt; adjacent opening &lt; wall &lt; RoomPlan opening). A window wall over a plain wall only sets
        /// the window flag (keeping the plain wall's height / offset); a plain wall never
        /// overwrites another wall (the first — nearest — wall painted keeps the stretch)
        /// unless `force` (a plain wall over a window stretch, legacy conversion).
        public void Paint(float a, float b, RectSpan span, bool force = false)
        {
            a = Math.Max(0f, a); b = Math.Min(length, b);
            if (b - a <= 1e-4f) return;
            SplitAt(a); SplitAt(b);
            int rank = span.Rank;
            for (int i = 0; i < _spans.Count; i++)
            {
                var s = _spans[i];
                if (s.b <= a + 1e-5f || s.a >= b - 1e-5f) continue;
                int have = s.Rank;
                if (rank < have) continue;
                if (rank == have && span.IsWall && s.IsWall)
                {
                    if (span.window && !s.window)
                        _spans[i] = new RectSpan(s.a, s.b, RectSpanKind.Wall, null, s.height, s.offset, true, s.touches);
                    else if (force && s.window && !span.window)
                        _spans[i] = new RectSpan(s.a, s.b, RectSpanKind.Wall, null, span.height, span.offset, false, s.touches);
                    continue;
                }
                if (rank == have && span.IsOpening && s.IsOpening && !force) continue;
                _spans[i] = new RectSpan(s.a, s.b, span.kind, span.type, span.height, span.offset, span.window, s.touches);
            }
        }

        /// Overwrites [a, b] with `span` whatever is there (reconciliation between two rects).
        public void Set(float a, float b, RectSpan span)
        {
            a = Math.Max(0f, a); b = Math.Min(length, b);
            if (b - a <= 1e-4f) return;
            SplitAt(a); SplitAt(b);
            for (int i = 0; i < _spans.Count; i++)
            {
                var s = _spans[i];
                if (s.b <= a + 1e-5f || s.a >= b - 1e-5f) continue;
                _spans[i] = span.WithRange(s.a, s.b);
            }
        }

        /// Makes [a, b] unknown where it is wall (never touches an opening): a door that only
        /// grazes this side (overlap &lt; MinOpeningM) is not this side's opening, but no wall
        /// stands there either.
        public void ClearWall(float a, float b)
        {
            a = Math.Max(0f, a); b = Math.Min(length, b);
            if (b - a <= 1e-4f) return;
            SplitAt(a); SplitAt(b);
            for (int i = 0; i < _spans.Count; i++)
            {
                var s = _spans[i];
                if (s.b <= a + 1e-5f || s.a >= b - 1e-5f || !s.IsWall) continue;
                _spans[i] = new RectSpan(s.a, s.b, RectSpanKind.Unknown, touches: s.touches);
            }
        }

        /// A neighbouring rect touches [a, b]: every UNKNOWN piece becomes an opening of
        /// `type` (default "adjacent") touching `rectId`; walls and RoomPlan openings keep
        /// their kind and only get `touches` (where not set yet). Never overrides a wall.
        public void Adjoin(float a, float b, string rectId, string type = RectSpanKind.Adjacent)
        {
            if (string.IsNullOrEmpty(rectId)) return;
            a = Math.Max(0f, a); b = Math.Min(length, b);
            if (b - a <= 1e-4f) return;
            SplitAt(a); SplitAt(b);
            for (int i = 0; i < _spans.Count; i++)
            {
                var s = _spans[i];
                if (s.b <= a + 1e-5f || s.a >= b - 1e-5f) continue;
                if (s.IsUnknown) _spans[i] = new RectSpan(s.a, s.b, RectSpanKind.Opening, type, touches: rectId);
                else if (s.touches == null) _spans[i] = s.WithTouches(rectId);
            }
        }

        /// Sets `touches` on [a, b] where it is not set yet (first neighbour wins);
        /// `passableOnly`: never on a wall span.
        public void Touch(float a, float b, string rectId, bool passableOnly = false)
        {
            if (string.IsNullOrEmpty(rectId)) return;
            a = Math.Max(0f, a); b = Math.Min(length, b);
            if (b - a <= 1e-4f) return;
            SplitAt(a); SplitAt(b);
            for (int i = 0; i < _spans.Count; i++)
            {
                var s = _spans[i];
                if (s.b <= a + 1e-5f || s.a >= b - 1e-5f || s.touches != null || (passableOnly && s.IsWall)) continue;
                _spans[i] = s.WithTouches(rectId);
            }
        }

        private void SplitAt(float x)
        {
            for (int i = 0; i < _spans.Count; i++)
            {
                var s = _spans[i];
                if (x > s.a + 1e-5f && x < s.b - 1e-5f)
                {
                    _spans[i] = s.WithRange(s.a, x);
                    _spans.Insert(i + 1, s.WithRange(x, s.b));
                    return;
                }
            }
        }

        /// The current spans (no merging) — for tests.
        public IReadOnlyList<RectSpan> Raw => _spans;

        /// Merged, sliver-free spans tiling [0, length]. `previous` (same side, last bake)
        /// pins boundaries that moved less than `snapM`.
        public RectEdgeBorder Build(RectEdgeBorder? previous = null, float snapM = DefaultSnapM)
            => new RectEdgeBorder(length, Normalize(_spans, length, previous, snapM));

        /// Merge → absorb slivers → snap → merge. Rules (RECT_EDGES_SPEC.md §1, step 5):
        /// an opening narrower than MinOpeningM, or any other span narrower than MinSpanM,
        /// joins its wider neighbour (taking that neighbour's attributes); narrowest first,
        /// repeated until none is left. A side shorter than that keeps one span.
        public static RectSpan[] Normalize(IReadOnlyList<RectSpan> input, float length, RectEdgeBorder? previous, float snapM)
        {
            var list = new List<RectSpan>(input);
            Merge(list);
            // A RoomPlan doorway never grows past what RoomPlan measured (Oct 15 2026):
            // a non-doorway sliver goes to a non-doorway neighbour, and one that only
            // touches doorways (or a doorway and the side's end) stays as its own span.
            while (list.Count > 1)
            {
                int pick = -1, host = -1;
                for (int i = 0; i < list.Count; i++)
                {
                    float min = list[i].IsOpening ? MinOpeningM : MinSpanM;
                    if (list[i].Width >= min - 1e-4f) continue;
                    int hostIndex = HostFor(list, i);
                    if (hostIndex < 0) continue;
                    if (pick < 0 || list[i].Width < list[pick].Width) { pick = i; host = hostIndex; }
                }
                if (pick < 0) break;
                var h = list[host];
                list[host] = h.WithRange(Math.Min(h.a, list[pick].a), Math.Max(h.b, list[pick].b));
                list.RemoveAt(pick);
                Merge(list);
            }
            if (previous.HasValue && previous.Value.IsComputed && list.Count > 1
                && Math.Abs(previous.Value.length - length) <= snapM)
            {
                var prev = previous.Value.spans;
                for (int i = 0; i + 1 < list.Count; i++)
                {
                    float x = list[i].b, best = x, bestD = snapM + 1e-6f;
                    for (int j = 0; j + 1 < prev.Length; j++)
                    {
                        float d = Math.Abs(prev[j].b - x);
                        if (d < bestD) { bestD = d; best = prev[j].b; }
                    }
                    if (best == x || best <= list[i].a + 1e-3f || best >= list[i + 1].b - 1e-3f) continue;
                    list[i] = list[i].WithRange(list[i].a, best);
                    list[i + 1] = list[i + 1].WithRange(best, list[i + 1].b);
                }
            }
            if (list.Count > 0)
            {
                list[0] = list[0].WithRange(0f, list[0].b);
                list[list.Count - 1] = list[list.Count - 1].WithRange(list[list.Count - 1].a, length);
            }
            return list.ToArray();
        }

        /// The neighbour sliver `i` joins: the wider one, but never a doorway unless the sliver
        /// is a doorway piece itself; -1 = keep it.
        private static int HostFor(List<RectSpan> list, int i)
        {
            int prev = i > 0 ? i - 1 : -1, next = i + 1 < list.Count ? i + 1 : -1;
            bool sliverIsDoorway = list[i].IsDoorway;
            bool okPrev = prev >= 0 && (sliverIsDoorway || !list[prev].IsDoorway);
            bool okNext = next >= 0 && (sliverIsDoorway || !list[next].IsDoorway);
            if (okPrev && okNext) return list[prev].Width >= list[next].Width ? prev : next;
            return okPrev ? prev : okNext ? next : -1;
        }

        private static void Merge(List<RectSpan> list)
        {
            for (int i = list.Count - 2; i >= 0; i--)
                if (list[i].SameAttributes(list[i + 1]))
                {
                    list[i] = list[i].WithRange(list[i].a, list[i + 1].b);
                    list.RemoveAt(i + 1);
                }
        }
    }

    /// <summary>
    /// All 4 sides of one rect, named for the field they border (min-corner
    /// origin before `yawDeg`: `minX`=x, `maxX`=x+w, `minZ`=z, `maxZ`=z+d).
    /// Hangs off `SpaceRect.borders` (null = uncomputed; reads as all unknown).
    /// </summary>
    public class SpaceRectBorders
    {
        /// Stored-format version (v3 = spans only).
        public const int Version = 3;

        public RectEdgeBorder minX = RectEdgeBorder.Unclassified;
        public RectEdgeBorder maxX = RectEdgeBorder.Unclassified;
        public RectEdgeBorder minZ = RectEdgeBorder.Unclassified;
        public RectEdgeBorder maxZ = RectEdgeBorder.Unclassified;

        /// <summary>
        /// The same borders seen from a frame turned by k quarter turns (canonical
        /// yaw = yaw − 90·k, ArenaPlacementMath.CanonicalizeTo). `w`/`d` are THIS
        /// rect's sizes. One turn maps maxX→minZ, maxZ→maxX, minX→maxZ, minZ→minX;
        /// spans are reversed where an edge's tangent direction flips.
        /// </summary>
        public SpaceRectBorders TurnedBy(int k, float w, float d)
        {
            var b = new SpaceRectBorders { minX = minX, maxX = maxX, minZ = minZ, maxZ = maxZ };
            k = ((k % 4) + 4) % 4;
            for (int i = 0; i < k; i++)
            {
                var next = new SpaceRectBorders
                {
                    minZ = b.maxX,
                    maxZ = b.minX,
                    maxX = b.maxZ.Reversed(w),
                    minX = b.minZ.Reversed(w),
                };
                b = next;
                float t = w; w = d; d = t;
            }
            return b;
        }

        /// Edge by its field name ("minX" | "maxX" | "minZ" | "maxZ").
        public RectEdgeBorder Edge(string side)
        {
            switch (side)
            {
                case "minX": return minX;
                case "maxX": return maxX;
                case "minZ": return minZ;
                case "maxZ": return maxZ;
                default: return RectEdgeBorder.Unclassified;
            }
        }

        public void SetEdge(string side, RectEdgeBorder value)
        {
            switch (side)
            {
                case "minX": minX = value; break;
                case "maxX": maxX = value; break;
                case "minZ": minZ = value; break;
                case "maxZ": maxZ = value; break;
            }
        }

        private IEnumerable<RectEdgeBorder> All()
        {
            yield return minX; yield return maxX; yield return minZ; yield return maxZ;
        }

        /// Sides with at least one RoomPlan door / opening.
        public int OpeningEdgeCount { get { int n = 0; foreach (var e in All()) if (e.HasOpening) n++; return n; } }
        /// Walled sides (<see cref="RectEdgeBorder.IsWalled"/>).
        public int WalledEdgeCount { get { int n = 0; foreach (var e in All()) if (e.IsWalled) n++; return n; } }
        /// Sides that are all unknown.
        public int UnknownEdgeCount { get { int n = 0; foreach (var e in All()) if (e.IsAllUnknown) n++; return n; } }
        /// Sides with no wall and no RoomPlan door/opening (unknown + adjacent openings only).
        public int OpenFloorEdgeCount { get { int n = 0; foreach (var e in All()) if (e.IsOpenFloor) n++; return n; } }
        /// Sides that are wall end to end (nothing passable).
        public int FullWallEdgeCount { get { int n = 0; foreach (var e in All()) if (e.IsFullWall) n++; return n; } }

        /// OPEN AREA (Aidan: "rects with 100% unknown edges can be considered
        /// connected from any side … a gymnasium floor or mall courtyard"):
        /// no side has a wall or a RoomPlan door/opening — every span is unknown or
        /// an adjacent-rect opening (neighbours touching it do not make it less open).
        public bool IsOpenArea => OpenFloorEdgeCount == 4;

        /// Nothing on any side is passable (every side is wall end to end).
        public bool IsWalledIn => FullWallEdgeCount == 4;
    }
}
#endif
